    const scan_no_clone_step = b.step("test-gap0900-scan-no-clone", "Run GAP-0900 scan-no-clone regression (bounded scan is O(result), no whole-graph deep clone)");
    scan_no_clone_step.dependOn(&run_scan_no_clone_tests.step);

    // SONNY-1218 (GEO-UP-006): the engine-direct node_scan_stream fast path
    // reads ONLY the persisted storage adapter, so on an in-memory deployment
    // (no `--data-dir`, `getGlobalAdapter() == null`) it must DECLINE to the
    // executor instead of serving a successful EMPTY row set. Asserts the
    // in-memory rows are correct for `RETURN n.p` / `RETURN n` / inline-map
    // predicates / filtered count, that `isEligible` agrees with `prepare`,
    // and that the fast path STILL engages when the adapter is present.
    const inmem_scan_decline_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_sonny1218_in_memory_node_scan.zig"), .target = target, .optimize = optimize });
    inmem_scan_decline_test_mod.addImport("geode", root_mod);
    const inmem_scan_decline_tests = b.addTest(.{ .root_module = inmem_scan_decline_test_mod });
    const run_inmem_scan_decline_tests = b.addRunArtifact(inmem_scan_decline_tests);
    shardDep(test_step, &run_inmem_scan_decline_tests.step, 1, test_shard_loads, test_shard_index);
    const inmem_scan_decline_step = b.step("test-sonny1218-in-memory-node-scan", "Run SONNY-1218 regression (engine-direct node scan declines without a storage adapter instead of answering empty)");
    inmem_scan_decline_step.dependOn(&run_inmem_scan_decline_tests.step);

    // SONNY-1229 (GEO-UP-002) P0: the engine-direct node_scan_stream fast path
    // has NO tenant logic, so a session bound to a concrete tenant was served
    // EVERY tenant's rows (and an unregistered tenant read everything) for
    // `MATCH (n:L) RETURN n.p` / `RETURN n` / `count(n)`. It must now DECLINE to
    // the tenant-aware executor whenever the session has a concrete tenant scope
    // or strict tenancy is effective. Needs `geode`, `rls` (rls_core) and
    // `rls_types` to publish + populate a live expr-RLS engine whose
    // HierarchyManager holds the registered tenants (the GAP-0846 seam).
    const sonny1229_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_sonny1229_strict_tenancy_read.zig"), .target = target, .optimize = optimize });
    sonny1229_test_mod.addImport("geode", root_mod);
    sonny1229_test_mod.addImport("rls", rls_mod);
    sonny1229_test_mod.addImport("rls_types", rls_types_mod);
    const sonny1229_tests = b.addTest(.{ .root_module = sonny1229_test_mod });
    const run_sonny1229_tests = b.addRunArtifact(sonny1229_tests);
    shardDep(test_step, &run_sonny1229_tests.step, 1, test_shard_loads, test_shard_index);
    const sonny1229_step = b.step("test-sonny1229-strict-tenancy-read", "Run SONNY-1229 regression (engine-direct reads are tenant-scoped: the node-scan fast path declines to the executor under a concrete tenant scope / strict tenancy)");
    sonny1229_step.dependOn(&run_sonny1229_tests.step);

    // SONNY-1318 (GEO-UP-005) P0: the `CALL algo.*` graph procedures
    // (algo_dispatch -> recursion_handler BFS/DFS/Dijkstra and
    // centrality_algorithms) had NO tenant handling at all, so a tenant could
    // traverse into and score another tenant's nodes through a procedure even
    // though the equivalent MATCH read is filtered. Also pins
    // schema_introspection to the same strict-tenancy resolver meta_dispatch
    // uses. Needs `geode`, `rls`/`rls_types` (live expr-RLS engine whose
    // HierarchyManager holds the registered tenants — the GAP-0846 seam) and
    // `schema_introspection` (its own module, the LSP metadata path).
    const sonny1318_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_sonny1318_procedure_tenancy.zig"), .target = target, .optimize = optimize });
    sonny1318_test_mod.addImport("geode", root_mod);
    sonny1318_test_mod.addImport("rls", rls_mod);
    sonny1318_test_mod.addImport("rls_types", rls_types_mod);
    sonny1318_test_mod.addImport("schema_introspection", schema_introspection_mod);
    const sonny1318_tests = b.addTest(.{ .root_module = sonny1318_test_mod });
    const run_sonny1318_tests = b.addRunArtifact(sonny1318_tests);
    shardDep(test_step, &run_sonny1318_tests.step, 1, test_shard_loads, test_shard_index);
    const sonny1318_step = b.step("test-sonny1318-procedure-tenancy", "Run SONNY-1318 regression (CALL algo.* traversal/centrality procedures and LSP schema introspection are tenant-scoped, fail-closed under strict tenancy)");
    sonny1318_step.dependOn(&run_sonny1318_tests.step);

    // SONNY-1318 review R1 — TSan companion: the same regression file compiled
    // with -fsanitize-thread so the SCOPED `algo.degree.stream` case that runs
    // over more than `Thresholds.forEach` (32) visible nodes exercises the real
    // `parallelForEach` worker fan-out under the thread sanitizer. The workers
    // must touch no tenant predicate, no shared allocator and no storage
    // adapter (scoped degrees are computed on the calling thread) — this step
    // is what proves it rather than asserting it. Opt-in (not part of the
    // default test_step): TSan adds ~5-8x overhead; built with tsanTest() (SONNY-6328).
    // Run via: zig build test-sonny1318-procedure-tenancy-tsan
    const sonny1318_tsan_mod = b.createModule(.{
        .root_source_file = b.path("tests/test_sonny1318_procedure_tenancy.zig"),
        .target = target,
        .optimize = .Debug,
        .link_libc = true,
        .sanitize_thread = true,
    });
    sonny1318_tsan_mod.addImport("geode", root_mod);
    sonny1318_tsan_mod.addImport("rls", rls_mod);
    sonny1318_tsan_mod.addImport("rls_types", rls_types_mod);
    sonny1318_tsan_mod.addImport("schema_introspection", schema_introspection_mod);
    const sonny1318_tsan_tests = tsanTest(b, sonny1318_tsan_mod);
    const run_sonny1318_tsan_tests = b.addRunArtifact(sonny1318_tsan_tests);
    const sonny1318_tsan_step = b.step(
        "test-sonny1318-procedure-tenancy-tsan",
        "TSan companion: SONNY-1318 scoped parallel degree path under -fsanitize-thread (race detection in the algo.degree.stream worker fan-out)",
    );
    sonny1318_tsan_step.dependOn(&run_sonny1318_tsan_tests.step);

    // SONNY-1326 (GEO-UP-005) P0: the EXPRESSION evaluation path in
    // `graph_algorithms.zig` (`shortestPath()`, `COUNT { … }`, `EXISTS { … }`
    // and pattern comprehensions) applied NO tenant scope at all, so a scoped
    // session still observed another tenant's nodes/edges through path length,
    // counts and existence even after SONNY-1318 filtered MATCH and
    // `CALL algo.*`. Needs `geode` plus `rls`/`rls_types` for the live
    // expr-RLS engine whose HierarchyManager holds the registered tenants.
    const sonny1326_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_sonny1326_expression_tenancy.zig"), .target = target, .optimize = optimize });
    sonny1326_test_mod.addImport("geode", root_mod);
    sonny1326_test_mod.addImport("rls", rls_mod);
    sonny1326_test_mod.addImport("rls_types", rls_types_mod);
    const sonny1326_tests = b.addTest(.{ .root_module = sonny1326_test_mod });
    const run_sonny1326_tests = b.addRunArtifact(sonny1326_tests);
    shardDep(test_step, &run_sonny1326_tests.step, 1, test_shard_loads, test_shard_index);
    const sonny1326_step = b.step("test-sonny1326-expression-tenancy", "Run SONNY-1326 regression (shortestPath(), COUNT{}, EXISTS{} and pattern comprehensions are tenant-scoped, fail-closed under strict tenancy)");
    sonny1326_step.dependOn(&run_sonny1326_tests.step);

    // SONNY-1330: parallel UNION arm thread safety. `tryParallelUnion` runs a
    // full query per arm on its own `std.Thread`; the hydrate-on-miss cache
    // accessors INSERT (and past the cap EVICT) into the process-wide bounded
    // node/edge/adjacency caches, moving the value slots that sibling arms hold
    // raw `*Node`/`*Edge` pointers into. Arms now run with hydration disabled
    // on their thread and the whole UNION falls back to the serial path if any
    // arm needed it. The regression drives a UNION whose arms must read
    // NON-RESIDENT nodes (store reopened cold against a persisted data dir) and
    // pins the rows to the serial path's rows.
    const sonny1330_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_sonny1330_parallel_union.zig"), .target = target, .optimize = optimize });
    sonny1330_test_mod.addImport("geode", root_mod);
    // SONNY-1330 review follow-up: this suite opens the store through the
    // PRODUCTION `initGlobalStore` path (data dir + storage adapter), unlike the
    // other `test-sonny*` suites, so the adapter emits a steady stream of
    // `geode.storage` INFO lines. The Zig 0.16 build runner pipes a
    // `--listen=-` test child's stderr and echoes it back under the step banner
    // with a red `failed command:` line even on a clean, exit-0 run. The test
    // silences the engine logger at startup (`silenceEngineLogs`); it needs the
    // SAME `logging` module instance the engine logs through to do that.
    sonny1330_test_mod.addImport("logging", logging_mod);
    const sonny1330_tests = b.addTest(.{ .root_module = sonny1330_test_mod });
    const run_sonny1330_tests = b.addRunArtifact(sonny1330_tests);
    // Bound the resident node/edge/adjacency caches HARD (16 shards x 4 entries)
    // so the seeded rows genuinely fall out of residency and the UNION arms must
    // take the hydrate-on-miss path this ticket forbids them. Without this the
    // reopen's lazy per-graph hydration leaves every row resident and the
    // regression proves nothing. See nodeCacheCapFromEnv in graph_store.zig.
    run_sonny1330_tests.setEnvironmentVariable("GEODE_NODE_CACHE_ENTRIES", "64");
    run_sonny1330_tests.setEnvironmentVariable("GEODE_EDGE_CACHE_ENTRIES", "64");
    run_sonny1330_tests.setEnvironmentVariable("GEODE_ADJ_CACHE_ENTRIES", "64");
    shardDep(test_step, &run_sonny1330_tests.step, 1, test_shard_loads, test_shard_index);
    const sonny1330_step = b.step("test-sonny1330-parallel-union", "Run SONNY-1330 regression (parallel UNION arms never mutate the shared bounded caches; a UNION with non-resident arms falls back to the serial path and returns the serial path's rows)");
    sonny1330_step.dependOn(&run_sonny1330_tests.step);

    // SONNY-1562: COUNT {} / EXISTS {} / pattern comprehensions found their
    // uncorrelated start nodes by walking the RESIDENT node cache, so on a
    // persisted store reopened cold they answered 0 / false / [] while the
    // equivalent MATCH returned every row. The regression reopens a real data
    // dir with the caches pinned to 64 entries (same wiring as SONNY-1330) and
    // pins the expression path's answers to the MATCH path's.
    const sonny1562_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_sonny1562_cold_subquery_scan.zig"), .target = target, .optimize = optimize });
    sonny1562_test_mod.addImport("geode", root_mod);
    sonny1562_test_mod.addImport("logging", logging_mod);
    const sonny1562_tests = b.addTest(.{ .root_module = sonny1562_test_mod });
    const run_sonny1562_tests = b.addRunArtifact(sonny1562_tests);
    run_sonny1562_tests.setEnvironmentVariable("GEODE_NODE_CACHE_ENTRIES", "64");
    run_sonny1562_tests.setEnvironmentVariable("GEODE_EDGE_CACHE_ENTRIES", "64");
    run_sonny1562_tests.setEnvironmentVariable("GEODE_ADJ_CACHE_ENTRIES", "64");
    shardDep(test_step, &run_sonny1562_tests.step, 1, test_shard_loads, test_shard_index);
    const sonny1562_step = b.step("test-sonny1562-cold-subquery-scan", "Run SONNY-1562 regression (COUNT{}, EXISTS{} and pattern comprehensions see every node of a cold, persisted store, not just the resident cache)");
    sonny1562_step.dependOn(&run_sonny1562_tests.step);

    // SONNY-1560: a pushed gRPC result must never pin the session.
    //
    // `handleExecuteStreaming` used to hold the session mutex for the ENTIRE
    // push loop (Issue #514's fix for a concurrent-Execute use-after-free), so
    // a peer that stopped draining its HTTP/2 flow-control window locked every
    // other statement on that session out for the vendored grpc-zig library's
    // 30 s `flow_credit_timeout_ns`. The suite drives `pushResultPages` through
    // its `PageSink` seam with stub sinks that stall, abandon, supersede, or
    // report a too-small window, and pins: the mutex is never held across a
    // page write, a normal reader gets every row, and every abandonment path
    // releases the session cursor deterministically.
    //
    // The suite reaches grpc_server.zig's public decls through
    // `src/grpc_server_test_shim.zig`, which is rooted at src/ so that file's
    // own `../server/*.zig` imports resolve; a module rooted at tests/ cannot
    // import it directly.
    const sonny1560_shim_mod = b.createModule(.{
        .root_source_file = b.path("src/grpc_server_test_shim.zig"),
        .target = target,
        .optimize = optimize,
    });
    sonny1560_shim_mod.link_libc = true;
    sonny1560_shim_mod.addImport("crypto_backend", crypto_backend_mod);
    sonny1560_shim_mod.addImport("geode", root_mod);
    sonny1560_shim_mod.addImport("schema", schema_mod);
    sonny1560_shim_mod.addImport("protobuf", protobuf_mod);
    sonny1560_shim_mod.addImport("grpc_server", grpc_server_mod);
    sonny1560_shim_mod.addImport("geode_auth", auth_mod);
    sonny1560_shim_mod.addImport("logging", logging_mod);
    sonny1560_shim_mod.addImport("build_options", build_options_mod);
    // SONNY-2729: server/rls_filter.zig re-exports rls_types' label-deny engine.
    sonny1560_shim_mod.addImport("rls_types", rls_types_mod);
    sonny1560_shim_mod.addOptions("openssl_config", openssl_options);

    const sonny1560_test_mod = b.createModule(.{
        .root_source_file = b.path("tests/test_sonny1560_grpc_flow_control.zig"),
        .target = target,
        .optimize = optimize,
    });
    sonny1560_test_mod.link_libc = true;
    sonny1560_test_mod.addImport("geode", root_mod);
    sonny1560_test_mod.addImport("schema", schema_mod);
    sonny1560_test_mod.addImport("protobuf", protobuf_mod);
    sonny1560_test_mod.addImport("grpc_impl", sonny1560_shim_mod);
    // The suite drives every `.err`-logging abandonment path on purpose; it
    // needs the SAME `logging` module instance the engine logs through to pin
    // the logger to `.fatal` and keep the build runner's piped-stderr echo
    // quiet on a clean run. Mirrors the SONNY-1330 target.
    sonny1560_test_mod.addImport("logging", logging_mod);
    const sonny1560_tests = b.addTest(.{ .root_module = sonny1560_test_mod });
    const run_sonny1560_tests = b.addRunArtifact(sonny1560_tests);
