    const knn_metric_mismatch_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_knn_metric_mismatch.zig"), .target = target, .optimize = optimize });
    knn_metric_mismatch_test_mod.addImport("geode", root_mod);
