    const sonny2751_step = b.step("test-sonny2751-readonly-security-ddl", "Run the SONNY-2751 regression (a read-only request refuses the security DDL, every other change and an unknown procedure, gRPC and the MCP read-only mode; SHOW, the read-only auth procedures and session statements still run)");
    sonny2751_step.dependOn(&run_sonny2751_tests.step);
    sonny2751_step.dependOn(&run_sonny2751_mcp_tests.step);

    // SONNY-2753: a GPS policy scoped to a graph covers that graph (and its
    // nodes and edges) only, deny and allow alike; a change of every graph at
    // once is refused by a deny on any of them.
    const sonny2753_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_sonny2753_graph_scoped_deny.zig"), .target = target, .optimize = optimize });
    sonny2753_test_mod.link_libc = true;
    sonny2753_test_mod.addImport("geode", root_mod);
    sonny2753_test_mod.addImport("schema", schema_mod);
    sonny2753_test_mod.addImport("protobuf", protobuf_mod);
    sonny2753_test_mod.addImport("grpc_impl", sonny1560_shim_mod);
    sonny2753_test_mod.addImport("logging", logging_mod);
    const sonny2753_tests = b.addTest(.{ .root_module = sonny2753_test_mod });
    const run_sonny2753_tests = b.addRunArtifact(sonny2753_tests);
    shardDep(test_step, &run_sonny2753_tests.step, 1, test_shard_loads, test_shard_index);
    const sonny2753_step = b.step("test-sonny2753-graph-scoped-deny", "Run the SONNY-2753 regression (a deny scoped to graph g refuses what happens on g only, procedures, nodes, edges and decryption included; a change of every graph at once is refused by a deny on any graph; graph-scoped allow covers its graph only; deny beats allow; cached verdicts are per graph)");
    sonny2753_step.dependOn(&run_sonny2753_tests.step);

    // SONNY-2756 (P23): the GPS policy catalog is read on every request while
    // policy DDL on other connections changes it.
    const sonny2756_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_sonny2756_policy_catalog_concurrency.zig"), .target = target, .optimize = optimize });
    sonny2756_test_mod.link_libc = true;
    sonny2756_test_mod.addImport("geode", root_mod);
    sonny2756_test_mod.addImport("logging", logging_mod);
    const sonny2756_tests = b.addTest(.{ .root_module = sonny2756_test_mod });
    const run_sonny2756_tests = b.addRunArtifact(sonny2756_tests);
    shardDep(test_step, &run_sonny2756_tests.step, 1, test_shard_loads, test_shard_index);
    const sonny2756_step = b.step("test-sonny2756-policy-catalog-concurrency", "Run the SONNY-2756 regression (a policy change waits for a decision walking the GPS policy catalog and a decision for a change in progress; one decision sees one catalog; no cached decision outlives a change; decisions, helpers and SHOW POLICIES stay well-formed during rounds of policy DDL)");
    sonny2756_step.dependOn(&run_sonny2756_tests.step);

    // SONNY-2782: with authentication disabled the QUIC and gRPC handlers
    // gate a request the same way (one shared request gate).
    const sonny2782_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_sonny2782_auth_disabled_transport_parity.zig"), .target = target, .optimize = optimize });
    sonny2782_test_mod.link_libc = true;
    sonny2782_test_mod.addImport("geode", root_mod);
    sonny2782_test_mod.addImport("schema", schema_mod);
    sonny2782_test_mod.addImport("protobuf", protobuf_mod);
    sonny2782_test_mod.addImport("grpc_impl", sonny1560_shim_mod);
    sonny2782_test_mod.addImport("logging", logging_mod);
    const sonny2782_tests = b.addTest(.{ .root_module = sonny2782_test_mod });
    const run_sonny2782_tests = b.addRunArtifact(sonny2782_tests);
    shardDep(test_step, &run_sonny2782_tests.step, 1, test_shard_loads, test_shard_index);
    const sonny2782_step = b.step("test-sonny2782-auth-disabled-transport-parity", "Run the SONNY-2782 regression (with authentication disabled every request runs on QUIC and gRPC alike, --insecure-allow-all or not; with it enabled the gates are unchanged; both handlers gate through the one shared request gate)");
    sonny2782_step.dependOn(&run_sonny2782_tests.step);

    // SONNY-2781: every action a GPS policy can name is enforced: the write
    // gate asks CREATE / UPDATE / DELETE / WRITE+SCHEMA per statement, the
    // read gate asks MATCH on every graph read, for every principal; a deny
    // naming UNWRAP_KEY (enforced nowhere) is refused.
    const sonny2781_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_sonny2781_gps_action_enforcement.zig"), .target = target, .optimize = optimize });
    sonny2781_test_mod.link_libc = true;
    sonny2781_test_mod.addImport("geode", root_mod);
    sonny2781_test_mod.addImport("schema", schema_mod);
    sonny2781_test_mod.addImport("protobuf", protobuf_mod);
    sonny2781_test_mod.addImport("grpc_impl", sonny1560_shim_mod);
    sonny2781_test_mod.addImport("logging", logging_mod);
    const sonny2781_tests = b.addTest(.{ .root_module = sonny2781_test_mod });
    const run_sonny2781_tests = b.addRunArtifact(sonny2781_tests);
    shardDep(test_step, &run_sonny2781_tests.step, 1, test_shard_loads, test_shard_index);
    const sonny2781_step = b.step("test-sonny2781-gps-action-enforcement", "Run the SONNY-2781 regression (a deny naming READ, MATCH, CREATE, UPDATE, DELETE, SCHEMA or WRITE stops exactly the statements that need it, PROFILE and EXPLAIN included, on its graph; an allow naming one action allows exactly that; cached verdicts are per action; a deny naming UNWRAP_KEY is refused)");
    sonny2781_step.dependOn(&run_sonny2781_tests.step);

    // GPS Phase 7 Task 7-1: bounded LRU decision cache tests.
    const gps_decision_cache_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_gps_decision_cache.zig"), .target = target, .optimize = optimize });
    gps_decision_cache_test_mod.addImport("geode", root_mod);
    const gps_decision_cache_tests = b.addTest(.{ .root_module = gps_decision_cache_test_mod });
    const run_gps_decision_cache_tests = b.addRunArtifact(gps_decision_cache_tests);
    shardDep(test_step, &run_gps_decision_cache_tests.step, 0, test_shard_loads, test_shard_index);
    const gps_decision_cache_step = b.step("test-gps-decision-cache", "Run GPS decision cache tests (Phase 7 Task 7-1)");
    gps_decision_cache_step.dependOn(&run_gps_decision_cache_tests.step);

    // GPS Phase 7 Task 7-2: ALTER POLICY DDL — parser + executor integration tests.
    const gps_alter_policy_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_gps_alter_policy.zig"), .target = target, .optimize = optimize });
    gps_alter_policy_test_mod.addImport("geode", root_mod);
    const gps_alter_policy_tests = b.addTest(.{ .root_module = gps_alter_policy_test_mod });
    const run_gps_alter_policy_tests = b.addRunArtifact(gps_alter_policy_tests);
    shardDep(test_step, &run_gps_alter_policy_tests.step, 1, test_shard_loads, test_shard_index);
    const gps_alter_policy_step = b.step("test-gps-alter-policy", "Run GPS ALTER POLICY DDL tests (Phase 7 Task 7-2)");
    gps_alter_policy_step.dependOn(&run_gps_alter_policy_tests.step);

    // GPS Phase 7 Task 7-3: SHOW GRANTS FOR <user> — parser + executor integration tests.
    const gps_show_grants_for_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_gps_show_grants_for.zig"), .target = target, .optimize = optimize });
    gps_show_grants_for_test_mod.addImport("geode", root_mod);
    const gps_show_grants_for_tests = b.addTest(.{ .root_module = gps_show_grants_for_test_mod });
    const run_gps_show_grants_for_tests = b.addRunArtifact(gps_show_grants_for_tests);
    shardDep(test_step, &run_gps_show_grants_for_tests.step, 0, test_shard_loads, test_shard_index);
    const gps_show_grants_for_step = b.step("test-gps-show-grants-for", "Run GPS SHOW GRANTS FOR <user> tests (Phase 7 Task 7-3)");
    gps_show_grants_for_step.dependOn(&run_gps_show_grants_for_tests.step);

    // CANARY: REQ=REQ-GPS-EXPLAIN-001; FEATURE="GPS EXPLAIN POLICY"; ASPECT=BuildStep; STATUS=TESTED; TEST=tests/test_gps_explain_policy.zig; OWNER=security; UPDATED=2026-05-21
    const gps_explain_policy_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_gps_explain_policy.zig"), .target = target, .optimize = optimize });
    gps_explain_policy_test_mod.addImport("geode", root_mod);
    const gps_explain_policy_tests = b.addTest(.{ .root_module = gps_explain_policy_test_mod });
    const run_gps_explain_policy_tests = b.addRunArtifact(gps_explain_policy_tests);
    shardDep(test_step, &run_gps_explain_policy_tests.step, 0, test_shard_loads, test_shard_index);
    const gps_explain_policy_step = b.step("test-gps-explain-policy", "Run GPS EXPLAIN POLICY FOR <query> tests (Phase 7 Task 7-4)");
    gps_explain_policy_step.dependOn(&run_gps_explain_policy_tests.step);

    // CANARY: REQ=REQ-GPS-WIRE-001; FEATURE="GPS Wire Principal Forwarding"; ASPECT=BuildStep; STATUS=TESTED; TEST=tests/test_gps_mcp_wire.zig; OWNER=security; UPDATED=2026-05-21
    // GPS Phase 7 Task 7-5: MCP wire-level Principal forwarding tests.
    // Schema field + server unpack wired; MCP send-side blocked on geode-client-zig update.
    const gps_mcp_wire_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_gps_mcp_wire.zig"), .target = target, .optimize = optimize });
    gps_mcp_wire_test_mod.addImport("geode", root_mod);
    gps_mcp_wire_test_mod.addImport("schema", schema_mod);
    const gps_mcp_wire_tests = b.addTest(.{ .root_module = gps_mcp_wire_test_mod });
    const run_gps_mcp_wire_tests = b.addRunArtifact(gps_mcp_wire_tests);
    shardDep(test_step, &run_gps_mcp_wire_tests.step, 0, test_shard_loads, test_shard_index);
    const gps_mcp_wire_step = b.step("test-gps-mcp-wire", "Run GPS MCP wire-level Principal forwarding tests (Phase 7 Task 7-5)");
    gps_mcp_wire_step.dependOn(&run_gps_mcp_wire_tests.step);

    // CANARY: REQ=REQ-GPS-WIRE-002; FEATURE="GPS Distributed Wire"; ASPECT=BuildStep; STATUS=TESTED; TEST=tests/test_gps_distributed_wire.zig; OWNER=security; UPDATED=2026-05-21
    // GPS Phase 7 Task 7-6: Distributed Principal envelope wire integration tests.
    const gps_distributed_wire_test_mod = b.createModule(.{ .root_source_file = b.path("tests/test_gps_distributed_wire.zig"), .target = target, .optimize = optimize });
    gps_distributed_wire_test_mod.addImport("geode", root_mod);
    gps_distributed_wire_test_mod.addImport("schema", schema_mod);
    const gps_distributed_wire_tests = b.addTest(.{ .root_module = gps_distributed_wire_test_mod });
    const run_gps_distributed_wire_tests = b.addRunArtifact(gps_distributed_wire_tests);
    shardDep(test_step, &run_gps_distributed_wire_tests.step, 0, test_shard_loads, test_shard_index);
    const gps_distributed_wire_step = b.step("test-gps-distributed-wire", "Run GPS distributed Principal envelope wire integration tests (Phase 7 Task 7-6)");
    gps_distributed_wire_step.dependOn(&run_gps_distributed_wire_tests.step);

    // -------------------------------------------------------------------------
    // Task 1: crypto_backend smoke test — proves the seam is wired correctly
    // in both -Dfips=false (std_shim) and -Dfips=true (OpenSSL FIPS) modes.
    // -------------------------------------------------------------------------
    const crypto_backend_smoke_mod = b.createModule(.{
        .root_source_file = b.path("src/crypto_backend_smoke_test.zig"),
        .target = target,
        .optimize = optimize,
    });
    crypto_backend_smoke_mod.addImport("crypto_backend", crypto_backend_mod);
    const crypto_backend_smoke_tests = b.addTest(.{ .root_module = crypto_backend_smoke_mod });
    const run_crypto_backend_smoke = b.addRunArtifact(crypto_backend_smoke_tests);
    const crypto_backend_smoke_step = b.step("test-crypto-backend-smoke", "Smoke test: crypto_backend seam wired + SHA-256 KAT + HMAC-SHA1 KAT");
    crypto_backend_smoke_step.dependOn(&run_crypto_backend_smoke.step);
    // Also wire into the main test step so `zig build test` includes it.
    shardDep(test_step, &run_crypto_backend_smoke.step, 1, test_shard_loads, test_shard_index);

    // -------------------------------------------------------------------------
    // Task 11: FIPS dual-mode parity/KAT test + fail-closed test
    // -------------------------------------------------------------------------

    // fips_parity_test: KAT vectors for SHA-256/SHA3-256/HMAC-SHA256/HMAC-SHA1/
    // AES-256-GCM/HKDF-SHA256/Ed25519/ECDSA-P256; passes under both backends.
    const fips_parity_mod = b.createModule(.{
        .root_source_file = b.path("src/fips_parity_test.zig"),
        .target = target,
        .optimize = optimize,
    });
    fips_parity_mod.addImport("crypto_backend", crypto_backend_mod);
    const fips_parity_tests = b.addTest(.{ .root_module = fips_parity_mod });
    const run_fips_parity = b.addRunArtifact(fips_parity_tests);
    const fips_parity_step = b.step("test-fips-parity", "Task 11: FIPS parity KAT — SHA-256/SHA3-256/HMAC-SHA256/HMAC-SHA1/AES-GCM/HKDF/Ed25519/ECDSA-P256 (both backends)");
    fips_parity_step.dependOn(&run_fips_parity.step);
    shardDep(test_step, &run_fips_parity.step, 1, test_shard_loads, test_shard_index);

    // fips_failclosed_test: asserts error.FipsUnsupported for argon2id/BLAKE2b/
    // BLAKE3 under -Dfips=true; asserts they work under -Dfips=false.
    // NOTE: types_hash module (src/types/hash.zig) imports storage/heap.zig
    // which has complex multi-module deps (GAP-413 BLOCKED).  The guard
    // patterns are inlined directly in the test file; build_options only.
    const fips_failclosed_mod = b.createModule(.{
        .root_source_file = b.path("src/fips_failclosed_test.zig"),
        .target = target,
        .optimize = optimize,
    });
    fips_failclosed_mod.addImport("build_options", build_options_mod);
    const fips_failclosed_tests = b.addTest(.{ .root_module = fips_failclosed_mod });
    const run_fips_failclosed = b.addRunArtifact(fips_failclosed_tests);
    const fips_failclosed_step = b.step("test-fips-failclosed", "Task 11: FIPS fail-closed gate — argon2id/BLAKE2b/BLAKE3 return FipsUnsupported under -Dfips=true");
    fips_failclosed_step.dependOn(&run_fips_failclosed.step);
    shardDep(test_step, &run_fips_failclosed.step, 1, test_shard_loads, test_shard_index);

    // test-fips-seam: runs both parity + failclosed steps
    const fips_seam_step = b.step("test-fips-seam", "Task 11: FIPS seam gate — parity KATs + fail-closed assertions (run under both -Dfips=false and -Dfips=true)");
    fips_seam_step.dependOn(&run_fips_parity.step);
    fips_seam_step.dependOn(&run_fips_failclosed.step);

    // Read-path performance enablement: GEODE_BUFFER_POOL_PAGES lets operators
    // size the engine page cache to available RAM for large working sets.
    // Run via `zig build test-buffer-pool-env`.
    const buffer_pool_env_test_mod = b.createModule(.{
        .root_source_file = b.path("tests/test_buffer_pool_env.zig"),
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    buffer_pool_env_test_mod.addImport("geode", root_mod);
    const buffer_pool_env_tests = b.addTest(.{ .root_module = buffer_pool_env_test_mod });
    const run_buffer_pool_env_tests = b.addRunArtifact(buffer_pool_env_tests);
    shardDep(test_step, &run_buffer_pool_env_tests.step, 1, test_shard_loads, test_shard_index);
    const buffer_pool_env_step = b.step("test-buffer-pool-env", "Run GEODE_BUFFER_POOL_PAGES env-knob regression (default=1024, explicit=N, bad-value=1024)");
    buffer_pool_env_step.dependOn(&run_buffer_pool_env_tests.step);

    // SONNY-2394: variable-length MATCH released the per-path rel-var edge list
    // / path arrays only for REJECTED paths; every accepted row leaked them on
    // the caller's allocator. Pins no-leak when unprojected and no premature
    // free when `r` is projected (directly or nested).
    const sonny2394_varlen_test_mod = b.createModule(.{
        .root_source_file = b.path("tests/test_sonny2394_varlen_rel_list_ownership.zig"),
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    sonny2394_varlen_test_mod.addImport("geode", root_mod);
    const sonny2394_varlen_tests = b.addTest(.{ .root_module = sonny2394_varlen_test_mod });
    const run_sonny2394_varlen_tests = b.addRunArtifact(sonny2394_varlen_tests);
    shardDep(test_step, &run_sonny2394_varlen_tests.step, 1, test_shard_loads, test_shard_index);
    const sonny2394_varlen_step = b.step("test-sonny2394-varlen-rel-list", "Run SONNY-2394 regression (variable-length MATCH frees accepted rows' rel-var list/path arrays unless the row projects them)");
    sonny2394_varlen_step.dependOn(&run_sonny2394_varlen_tests.step);

    // SONNY-2439: self-tests of the shared perf-claim gate (enforced only under
    // GEODE_PERF_GATES=enforce, reported by default, selftest violation hook).
    const perf_gate_tests = b.addTest(.{ .root_module = perf_gate_mod });
    const run_perf_gate_tests = b.addRunArtifact(perf_gate_tests);
    shardDep(test_step, &run_perf_gate_tests.step, 1, test_shard_loads, test_shard_index);
    const perf_gate_step = b.step("test-perf-gate", "Run the shared perf-claim gate self-tests (SONNY-2439: perf claims are reported unless GEODE_PERF_GATES=enforce)");
    perf_gate_step.dependOn(&run_perf_gate_tests.step);

    // SONNY-2394: root cause of the test-remote-kms-hardening ConcurrencyStress
    // flake -- the remote-KMS client's response wait was a retry count, not a
    // wall-clock deadline -- plus the server's handling of re-announced streams.
    const sonny2394_kms_deadline_tests = b.addTest(.{ .root_module = b.createModule(.{ .root_source_file = b.path("tests/test_sonny2394_kms_client_deadline.zig"), .target = target, .optimize = optimize }) });
    sonny2394_kms_deadline_tests.root_module.addImport("transport/quic", transport_quic_mod);
    sonny2394_kms_deadline_tests.root_module.addImport("vendor_quic", quic_ext_mod);
    sonny2394_kms_deadline_tests.root_module.addImport("security/kms_remote", kms_remote_mod);
    sonny2394_kms_deadline_tests.root_module.addImport("tls_material", tls_material_mod); // SONNY-6442: kms_test_tls.zig
    sonny2394_kms_deadline_tests.root_module.link_libc = true;
    const run_sonny2394_kms_deadline_tests = b.addRunArtifact(sonny2394_kms_deadline_tests);
    shardDep(test_step, &run_sonny2394_kms_deadline_tests.step, 1, test_shard_loads, test_shard_index);
    const sonny2394_kms_deadline_step = b.step("test-sonny2394-kms-client-deadline", "Run SONNY-2394 regression (remote-KMS client waits on a wall-clock deadline, fails fast on a closed connection; server ignores re-announced streams)");
    sonny2394_kms_deadline_step.dependOn(&run_sonny2394_kms_deadline_tests.step);

    // SONNY-2394 (review): a QUIC listener with no certificate self-signs one
    // only in dev posture or when explicitly enabled; production posture
    // (release build or GEODE_ENV=production) refuses to start. The same
    // binary runs in three environments so both postures and the opt-in are
    // exercised end to end.
    const cert_posture_tests = b.addTest(.{ .root_module = b.createModule(.{ .root_source_file = b.path("tests/test_sonny2394_cert_autogen_posture.zig"), .target = target, .optimize = optimize }) });
    cert_posture_tests.root_module.addImport("transport/quic", transport_quic_mod);
    cert_posture_tests.root_module.addImport("vendor_quic", quic_ext_mod);
    // The startup path: `geode serve` self-signs through cert_gen.
    cert_posture_tests.root_module.addImport("cert_gen", cert_provided_mod);
    cert_posture_tests.root_module.link_libc = true;
    const cert_posture_step = b.step("test-sonny2394-cert-autogen-posture", "Run SONNY-2394 regression (listener certificate auto-generation fails closed in production posture; dev posture and explicit opt-in still self-sign)");
    const run_cert_posture_prod = b.addRunArtifact(cert_posture_tests);
    run_cert_posture_prod.setEnvironmentVariable("GEODE_ENV", "production");
    run_cert_posture_prod.removeEnvironmentVariable("GEODE_TLS_AUTOGENERATE_CERT");
    const run_cert_posture_optin = b.addRunArtifact(cert_posture_tests);
    run_cert_posture_optin.setEnvironmentVariable("GEODE_ENV", "production");
    run_cert_posture_optin.setEnvironmentVariable("GEODE_TLS_AUTOGENERATE_CERT", "1");
    const run_cert_posture_dev = b.addRunArtifact(cert_posture_tests);
    run_cert_posture_dev.removeEnvironmentVariable("GEODE_ENV");
    run_cert_posture_dev.removeEnvironmentVariable("GEODE_TLS_AUTOGENERATE_CERT");
    for ([_]*std.Build.Step.Run{ run_cert_posture_prod, run_cert_posture_optin, run_cert_posture_dev }) |run_cert_posture| {
        shardDep(test_step, &run_cert_posture.step, 1, test_shard_loads, test_shard_index);
        cert_posture_step.dependOn(&run_cert_posture.step);
    }
}
